const cfg = $input.first().json;
const rawStores = String(cfg.storesCsv || '').split(',').map((s) => s.trim().toLowerCase()).filter(Boolean);
const dropThresholdPct = Number(cfg.dropThresholdPct || 5);
const checkedAtUtc = String(cfg.checkedAtUtc || new Date().toISOString());

const items = [];
for (const rawHost of rawStores) {
  const cleanHost = rawHost.replace(/^https?:\/\//, '').replace(/\/.*$/, '').trim();
  if (!cleanHost || !cleanHost.includes('.') || /^(localhost|127\.|10\.|192\.168\.|169\.254\.)/.test(cleanHost)) {
    continue;
  }
  items.push({
    json: {
      storeDomain: cleanHost,
      feedUrl: `https://${cleanHost}/products.json?limit=250`,
      dropThresholdPct,
      checkedAtUtc
    }
  });
}
return items;

const staticData = $getWorkflowStaticData('global');
if (!staticData.skuSnapshots) {
  staticData.skuSnapshots = {};
}

const events = [];
const inputItems = $input.all();
const upstreamStores = $items('Expand Public Store Feed URLs');

for (let i = 0; i < inputItems.length; i += 1) {
  const payload = inputItems[i].json || {};
  const meta = (upstreamStores[i] && upstreamStores[i].json) ? upstreamStores[i].json : {};
  const domain = meta.storeDomain || 'unknown-store';
  const thresholdPct = Number(meta.dropThresholdPct || 5);
  const checkedAtUtc = meta.checkedAtUtc || new Date().toISOString();
  const products = Array.isArray(payload.products) ? payload.products : [];

  for (const product of products) {
    const handle = String(product.handle || '');
    const title = String(product.title || handle || 'Untitled Product');
    const variants = Array.isArray(product.variants) ? product.variants : [];

    for (const variant of variants) {
      const skuKey = `${domain}::${variant.id}`;
      const currentPrice = Number(variant.price);
      const currentAvailable = Boolean(variant.available);
      if (!Number.isFinite(currentPrice)) continue;

      const prev = staticData.skuSnapshots[skuKey];
      if (prev) {
        const delta = Number((currentPrice - prev.price).toFixed(2));
        const deltaPct = prev.price > 0 ? Number(((delta / prev.price) * 100).toFixed(2)) : 0;
        let eventType = '';
        if (delta < 0 && Math.abs(deltaPct) >= thresholdPct) {
          eventType = 'PRICE_DROP';
        } else if (delta > 0 && Math.abs(deltaPct) >= thresholdPct) {
          eventType = 'PRICE_INCREASE';
        } else if (prev.available === true && currentAvailable === false) {
          eventType = 'OUT_OF_STOCK';
        } else if (prev.available === false && currentAvailable === true) {
          eventType = 'BACK_IN_STOCK';
        }

        if (eventType) {
          events.push({
            json: {
              hasChange: true,
              checkedAtUtc,
              storeDomain: domain,
              eventType,
              productTitle: title,
              variantTitle: String(variant.title || 'Default'),
              sku: String(variant.sku || variant.id),
              previousPrice: prev.price,
              currentPrice,
              delta,
              deltaPct,
              previousAvailable: prev.available,
              currentAvailable,
              productUrl: `https://${domain}/products/${handle}`
            }
          });
        }
      }
      staticData.skuSnapshots[skuKey] = {
        price: currentPrice,
        available: currentAvailable,
        title,
        updatedAt: checkedAtUtc
      };
    }
  }
}

if (events.length === 0) {
  return [{
    json: {
      hasChange: false,
      checkedAtUtc: new Date().toISOString(),
      trackedSkus: Object.keys(staticData.skuSnapshots).length,
      note: 'No price or stock changes crossed alert threshold in this cycle.'
    }
  }];
}
return events;
